void append(int value) {
  var newNode = Node(value);
  if (head == null) { head = newNode; return; }
  var current = head;
  while (current!.next != null) current = current.next;
  current.next = newNode;
}

void prepend(int value) {
  var newNode = Node(value);
  newNode.next = head;
  head = newNode;
