Node? merge(Node? l1, Node? l2) {
  if (l1 == null) return l2;
  if (l2 == null) return l1;
  if (l1.value < l2.value) {
    l1.next = merge(l1.next, l2);
    return l1;
  } else {
    l2.next = merge(l1, l2.next);
    return l2;
  }
}

class TreeNode {
  int value;
  TreeNode? left;
  TreeNode? right;
  TreeNode(this.value);
}

void inorder(TreeNode? node, List<int> res) {
  if (node == null) return;
  inorder(node.left, res);
  res.add(node.value);
  inorder(node.right, res);
}

TreeNode? insert(TreeNode? root, int val) {
  if (root == null) return TreeNode(val);
  if (val < root.value) root.left = insert(root.left, val);
  else root.right = insert(root.right, val);
  return root;
}

int height(TreeNode? node) {
  if (node == null) return 0;
  return 1 + max(height(node.left), height(node.right));
}

bool isBalanced(TreeNode? node) {
  if (node == null) return true;
  int lh = height(node.left), rh = height(node.right);
  return (lh - rh).abs() <= 1 && isBalanced(node.left) && isBalanced(node.right);
}

List<int> levelOrder(TreeNode? root) {
  if (root == null) return [];
  List<int> res = [];
  Queue<TreeNode> q = Queue()..add(root);
  while (q.isNotEmpty) {
    var n = q.removeFirst(); res.add(n.value);
    if (n.left != null) q.add(n.left!);
    if (n.right != null) q.add(n.right!);
  }
  return res;
}

int findMax(TreeNode? node) {
