List<int> bubbleSort(List<int> arr) {
  int n = arr.length;
  for (int i = 0; i < n - 1; i++) {
    for (int j = 0; j < n - i - 1; j++) {
      if (arr[j] > arr[j + 1]) {
        int temp = arr[j]; arr[j] = arr[j + 1]; arr[j + 1] = temp;
      }
    }
  }
  return arr;
}

List<double> quickSort(List<double> arr) {
  if (arr.length <= 1) return arr;
  double pivot = arr[arr.length ~/ 2];
  List<double> less = arr.where((x) => x < pivot).toList();
  List<double> equal = arr.where((x) => x == pivot).toList();
  List<double> greater = arr.where((x) => x > pivot).toList();
  return quickSort(less) + equal + quickSort(greater);
}

