List<String> mergeSort(List<String> arr) {
  if (arr.length <= 1) return arr;
  int mid = arr.length ~/ 2;
  List<String> left = mergeSort(arr.sublist(0, mid));
  List<String> right = mergeSort(arr.sublist(mid));
  return _merge(left, right);
}
List<String> _merge(List<String> a, List<String> b) {
  List<String> res = []; int i = 0, j = 0;
  while (i < a.length && j < b.length) { if (a[i].compareTo(b[j]) <= 0) res.add(a[i++]); else res.add(b[j++]); }
  return res + a.sublist(i) + b.sublist(j);
}

int factorial(int n) {
  if (n <= 1) return 1; // base case
  return n * factorial(n - 1); // recursive case
}

int fib(int n) {
  if (n <= 1) return n; // base cases
  return fib(n - 1) + fib(n - 2);
}

int sumList(List<int> nums, [int i = 0]) {
  if (i >= nums.length) return 0; // base case
  return nums[i] + sumList(nums, i + 1);
}

String reverse(String s) {
  if (s.length <= 1) return s; // base case
  return reverse(s.substring(1)) + s[0];
}

